+const fs = require('fs');
+
+function main() {
+  const args = process.argv.slice(2);
+
+  if (args.length === 0) {
+    console.log('鐢ㄦ硶: node validate-jsonl.js <鏂囦欢璺緞>');
+    process.exit(1);
+  }
+
+  const filePath = args[0];
+
+  if (!fs.existsSync(filePath)) {
+    console.error(`鏂囦欢閿欒: ${filePath} 涓嶅瓨鍦╜);
+    process.exit(1);
+  }
+
+  const content = fs.readFileSync(filePath, 'utf-8');
+  const lines = content.split(/\r?\n/);
+
+  let totalLines = 0;
+  let validCount = 0;
+  let errorCount = 0;
+
+  for (let i = 0; i < lines.length; i++) {
+    const line = lines[i].trim();
+    if (line === '') continue;
+
+    totalLines++;
+
+    try {
+      JSON.parse(line);
+      validCount++;
+    } catch (e) {
+      errorCount++;
+      console.log(`绗?${i + 1} 琛? ${e.message}`);
+    }
+  }
+
+  console.log(`\n鎬昏: ${totalLines} 琛宍);
+  console.log(`鍚堟硶JSON: ${validCount} 琛宍);
+  console.log(`閿欒JSON: ${errorCount} 琛宍);
+}
+
+main();
